const r = $json;
let row = {};
try { row = $('Montar consulta').item.json; } catch (e) { row = {}; }

let leadPending = {};
try { leadPending = $('Ler leads pendentes').item.json; } catch (e) { leadPending = {}; }

const status = (r.status != null ? r.status : (r.data && r.data.status)) || '';
const externalStatus = r.external_status || r.data?.external_status || '';

// DEFINIÇÃO CORRETA DE STATUS FINAIS (Acionáveis)
const APPROVED_FINAL = ['approved', 'pre_approved', 'comite_approved'];
const DENIED_FINAL   = ['denied', 'fails_to_process', 'lost', 'cancelled'];
const FORMALIZATION  = ['formalization'];
const WON_FINAL      = ['won'];
const FAIL_CONTACT   = ['fail_to_contact'];

let outcome = 'pending';

// Verifica se existe conteúdo real no offer_data
const offerData = r.offer_data || r.data?.offer_data || null;

// Classificação: Se aprovado ou pré-aprovado pela Fiserv, é uma oferta!
if (APPROVED_FINAL.includes(status) || externalStatus.toLowerCase().includes('aprovado')) {
    outcome = 'offer';
} else if (DENIED_FINAL.includes(status)) {
    outcome = 'rejected';
} else if (FORMALIZATION.includes(status)) {
    outcome = 'formalization';
} else if (FAIL_CONTACT.includes(status)) {
    outcome = 'fail_to_contact';
} else if (WON_FINAL.includes(status)) {
    outcome = 'won';
} else {
    outcome = 'pending';
}

// 🛡️ TRAVA DE IDEMPOTÊNCIA BLINDADA:
// Checa se a oferta ou recusa já foi enviada anteriormente para este lead,
// seja pelo node 'Montar consulta' ou direto de 'Ler leads pendentes'.
const alreadySent = Boolean(
    row._fiserv_offer_sent === 'true' || row._fiserv_offer_sent === true ||
    row.fiserv_offer_sent === 'true' || row.fiserv_offer_sent === true ||
    leadPending.fiserv_offer_sent === 'true' || leadPending.fiserv_offer_sent === true ||
    leadPending.metadata?.fiserv_offer_sent === 'true' || leadPending.metadata?.fiserv_offer_sent === true
);

// Decidido apenas se houver desfecho E NUNCA tiver sido enviado antes
const decided = (outcome !== 'pending') && !alreadySent;

// Detecta se algo mudou em relação ao que está no banco
const currentStatus   = row._current_status   || leadPending.current_fiserv_status || '';
const currentExternal = row._current_external || leadPending.current_external_status || '';

const status_changed  = !alreadySent && (
                        decided ||
                        (status !== currentStatus) ||
                        (externalStatus !== currentExternal));

// 🛡️ Sanitização de nome: Remove prefixo de CNPJ e sufixo de CPF/CNPJ de MEI
let rawName = row._contact_name || leadPending.name || 'Parceiro';
let cleanName = rawName
  .replace(/^\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}\s*[-–—]?\s*/i, '')
  .replace(/\s*[-–—]?\s*\d{11}$/i, '')
  .replace(/\s*[-–—]?\s*\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}$/i, '')
  .trim();
if (!cleanName || cleanName.length < 2) cleanName = 'Parceiro';
const name = cleanName;

let message = '';
let should_simulate = false;
let simAmount = 0;
let simInstallments = 24;
let approvedLimit = 0;
const reqAmount = parseFloat(row._requested_amount || leadPending.requested_amount || 0);
let maxTerm = 24;
let tax = '';

// Se já foi enviado, NÃO monta mensagem nem simula novamente
if (!alreadySent) {
  if (outcome === 'offer') {
    // Limite líquido aprovado pela Fiserv (sem TAC e IOF)
    let rawApproved = r.amount || r.data?.amount || offerData?.amount || null;
    if (!rawApproved && offerData?.SomaPrincipal) {
      const soma = parseFloat(offerData.SomaPrincipal);
      const iof = parseFloat(offerData.VlrIOF || 0);
      const tac = parseFloat(offerData.VlrTAC || 0);
      rawApproved = (soma > (iof + tac) && (iof > 0 || tac > 0)) ? (soma - iof - tac) : soma;
    }
    const amount = rawApproved || row._requested_amount || leadPending.requested_amount || '';
    const term   = offerData?.installments  || r.data?.installments || '24';
    tax          = offerData?.PercJurosMensal || '';
    approvedLimit = parseFloat(amount || 0);
    maxTerm = parseInt(term || 24);

    // Regra de parcelas: teto em 24 meses ou o limite máximo de parcelas aprovado pelo comitê
    simInstallments = Math.min(24, maxTerm > 0 ? maxTerm : 24);

    // Regra de valor:
    // Caso 1: Aprovado >= Pedido -> Simula o valor solicitado
    // Caso 2: Aprovado < Pedido -> Simula o valor máximo aprovado
    if (approvedLimit > 0 && reqAmount > 0) {
      simAmount = (approvedLimit >= reqAmount) ? reqAmount : approvedLimit;
    } else if (approvedLimit > 0) {
      simAmount = approvedLimit;
    } else if (reqAmount > 0) {
      simAmount = reqAmount;
    } else {
      simAmount = 50000;
    }
    simAmount = Math.floor(simAmount);

    const loanId = (r.loan_request_id != null ? r.loan_request_id : (row.loan_request_id || leadPending.loan_request_id));
    should_simulate = Boolean(loanId && simAmount > 0);

    // Fallback caso a simulação posterior falhe
    const amountFmt = approvedLimit ? approvedLimit.toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}) : '';
    message = `🎉 *Boa notícia, ${name}!*\\n\\n` +
      `A análise do seu CNPJ foi concluída e você tem crédito pré-aprovado!\\n\\n` +
      (amountFmt ? `💰 *Limite aprovado:* R$ ${amountFmt}\\n` : '') +
      (term  ? `📅 *Prazo:* até ${term} parcelas\\n` : '') +
      (tax   ? `📉 *Taxa:* ${tax}% a.m.\\n\\n` : '\\n') +
      `Você pode simular diferentes valores e prazos (de 6 a ${maxTerm} meses) dentro do seu limite aprovado.\\n\\n` +
      `👉 *Quer simular agora?* Me diga o valor que precisa e em quantas parcelas (de 6 a ${maxTerm} parcelas)!`;

  } else if (outcome === 'rejected') {
    message = `Olá, *${name}*!\\n\\n` +
      `Após a avaliação do comitê Fiserv, infelizmente não conseguimos liberar uma oferta de crédito para o seu CNPJ neste momento.\\n\\n` +
      `Isso não é definitivo! Você pode tentar novamente em *30 dias*.\\n\\n` +
      `Central de Atendimento: *4004-2233*\\n\\n` +
      `Obrigado pela confiança na Ticket! 🙏`;

  } else if (outcome === 'fail_to_contact') {
    message = `Olá, *${name}*!\\n\\n` +
      `A nossa mesa de crédito tentou entrar em contato com você por telefone para prosseguir com a análise, mas infelizmente não conseguiu. 😕\\n\\n` +
      `👉 *Qual é o melhor telefone e horário para nossa equipe te ligar?*`;

  } else if (outcome === 'formalization') {
    message = `Olá, *${name}*! Excelente notícia!\\n\\n` +
      `Sua proposta de crédito foi *100% aprovada* e está agora na fase final de Assinatura e Formalização! 🎉\\n\\n` +
      `Fique de olho no seu e-mail e nos seus canais de contato para assinar o contrato digital. Qualquer dúvida, é só chamar!`;

  } else if (outcome === 'won') {
    message = `Parabéns, *${name}*! 🚀\\n\\n` +
      `Seu crédito foi liberado com sucesso e o dinheiro já deve estar disponível na sua conta!\\n\\n` +
      `Agradecemos por escolher a Ticket e a Fiserv para turbinar o seu negócio. Caso precise de mais alguma coisa no futuro, é só me chamar aqui!`;
  }
}

return {
  _conversation_id: row._conversation_id || leadPending.conversation_id,
  _row_id:         row._row_id || leadPending.id,
  _tenant_id:      row._tenant_id || leadPending.tenant_id,
  _phone:          row._phone || leadPending.phone,
  _campaign_id:    row._campaign_id || leadPending.campaign_id,
  _contact_name:   name,
  cnpj:            row.cnpj || leadPending.cnpj,
  loan_request_id: (r.loan_request_id != null ? r.loan_request_id : (row.loan_request_id || leadPending.loan_request_id)),
  fiserv_ok:       r.ok,
  fiserv_http:     r.http_status,
  status:          status,
  external_status: externalStatus,
  offer_data:      offerData,
  outcome:         outcome,
  decided:         decided,
  status_changed:  status_changed,
  message_content: message,
  should_simulate: should_simulate,
  simulated_amount: simAmount,
  simulated_installments: simInstallments,
  approved_limit:  approvedLimit,
  requested_amount: reqAmount,
  max_installments: maxTerm,
  taxa_aprovada:   tax,
  has_simulation:  false,
  interactive_buttons: null,
  simulation_data: null
};

const rSim = $json; // Retorno do subworkflow Ferramenta Fiserv (simulate)
let prev = {};
try {
  prev = $('Classificar resultado').item.json;
} catch (e) {
  prev = {};
}

const ok = rSim.ok === true;
const simData = rSim.simulation_data || rSim.data?.simulation_data || rSim.data || {};
const parcelaVal = simData.VlrParcela || simData.installment_value || simData.valor_parcela || null;
const taxaVal = simData.PercJurosMensal || simData.monthly_interest || simData.taxa_mensal || prev.taxa_aprovada || '';

const name = prev._contact_name || 'Parceiro';
const approvedLimit = prev.approved_limit || 0;
const reqAmount = prev.requested_amount || 0;
const simAmount = prev.simulated_amount || reqAmount || approvedLimit;
const simTerm = prev.simulated_installments || 24;

const approvedFmt = approvedLimit ? Number(approvedLimit).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}) : '';
const reqFmt = reqAmount ? Number(reqAmount).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}) : '';
const simAmountFmt = simAmount ? Number(simAmount).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}) : '';
const parcelaFmt = parcelaVal ? Number(parcelaVal).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}) : '';
const taxaFmt = taxaVal ? Number(taxaVal).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}) : '';

let message = '';
let hasSimulation = false;
let buttons = null;

if (ok && parcelaVal) {
  hasSimulation = true;
  buttons = {
    tipo: "botoes",
    opcoes: ["Falar especialista", "Nova simulação"]
  };

  // CASO 1: Limite aprovado maior ou igual ao solicitado (ex: pediu 80k e aprovou 100k)
  if (reqAmount <= 0 || approvedLimit >= reqAmount) {
    message = `🎉 *Boa notícia, ${name}!*\n\n` +
      `A análise do seu CNPJ foi concluída e você tem um limite de crédito de até *R$ ${approvedFmt}*!\n\n` +
      `Já calculamos a sua simulação inicial para os *R$ ${simAmountFmt}* solicitados:\n` +
      `💰 *${simTerm} parcelas de R$ ${parcelaFmt}*\n` +
      (taxaFmt ? `📉 *Taxa:* ${taxaFmt}% a.m.\n\n` : '\n') +
      `Podemos seguir com essa condição ou prefere simular em outro prazo?`;
  } else {
    // CASO 2: Limite aprovado menor do que o solicitado (ex: pediu 80k e comitê aprovou 60k)
    message = `🎉 *Boa notícia, ${name}!*\n\n` +
      `A análise do comitê liberou um limite especial de até *R$ ${approvedFmt}* para a sua empresa (um pouco abaixo dos R$ ${reqFmt} solicitados).\n\n` +
      `Já adiantamos e calculamos a sua proposta no valor máximo liberado:\n` +
      `💰 *${simTerm} parcelas de R$ ${parcelaFmt}*\n` +
      (taxaFmt ? `📉 *Taxa:* ${taxaFmt}% a.m.\n\n` : '\n') +
      `Podemos seguir com essa condição ou prefere simular em outro prazo?`;
  }
} else {
  // Fallback seguro caso a simulação retorne erro
  message = prev.message_content;
  hasSimulation = false;
}

return {
  ...prev,
  message_content: message,
  interactive_buttons: buttons,
  has_simulation: hasSimulation,
  simulation_data: hasSimulation ? {
    amount: simAmount,
    installments: simTerm,
    installment_value: parcelaVal ? Number(parcelaVal) : null,
    monthly_interest: taxaVal ? Number(taxaVal) : null,
    total_debt: simData.total_debt ? Number(simData.total_debt) : (parcelaVal ? Number(parcelaVal) * simTerm : null),
    VlrParcela: parcelaVal ? Number(parcelaVal) : null,
    PercJurosMensal: taxaVal ? Number(taxaVal) : null
  } : null
};
